#!/usr/bin/env bash
# JNS Network Monitor UI enhancement deployment
# Version v0.3.28: read-only VLAN discovery, switch-port VLAN detail and optional topology overlay.
# Run as root on Node C. CT130 is updated in place; no reinstall or network changes.
set -Eeuo pipefail
VMID=130
APP_DIR=/opt/jns-netmon
SERVICE=jns-netmon.service
VERSION=0.3.28
APP_
HTML_
fail(){ echo "ERROR: $*" >&2; exit 1; }
[[ $EUID -eq 0 ]] || fail "Run as root on Node C."
command -v pct >/dev/null || fail "pct not found."
pct status "$VMID" | grep -q 'status: running' || fail "CT130 is not running."
pct exec "$VMID" -- systemctl is-active --quiet "$SERVICE" || fail "JNS service is not active."
OLD_HEALTH="$(pct exec "$VMID" -- curl -fsS --max-time 5 http://127.0.0.1:8081/health)"
CURRENT_VERSION="$(python3 - "$OLD_HEALTH" <<'PYHEALTH'
import json,sys
try:
    data=json.loads(sys.argv[1])
    version=data.get("version")
except Exception as exc:
    raise SystemExit(f"Invalid CT130 health response: {exc}")
if not isinstance(version,str) or not version:
    raise SystemExit(f"CT130 health response has no version: {sys.argv[1]}")
print(version)
PYHEALTH
)"
echo "Current CT130 version: $CURRENT_VERSION"
BACKUP="/root/jns-netmon-backup-v${VERSION}-$(date +%Y%m%d-%H%M%S)"
pct exec "$VMID" -- mkdir -m 700 -p "$BACKUP"
pct exec "$VMID" -- cp -a "$APP_DIR/app.py" "$BACKUP/app.py"
pct exec "$VMID" -- cp -a "$APP_DIR/index.html" "$BACKUP/index.html"
printf '%s' "$APP_B64" | base64 -d >"/tmp/jns-netmon-app-v${VERSION}.py"
printf '%s' "$HTML_B64" | base64 -d >"/tmp/jns-netmon-index-v${VERSION}.html"
CHANGED=0
rollback(){
  echo "Update failed; restoring the backed-up app and UI from $BACKUP" >&2
  pct exec "$VMID" -- cp -a "$BACKUP/app.py" "$APP_DIR/app.py" || true
  pct exec "$VMID" -- cp -a "$BACKUP/index.html" "$APP_DIR/index.html" || true
  pct exec "$VMID" -- systemctl restart "$SERVICE" || true
}
on_exit(){ rc=$?; if [[ $rc -ne 0 && $CHANGED -eq 1 ]]; then rollback; fi; rm -f "/tmp/jns-netmon-app-v${VERSION}.py" "/tmp/jns-netmon-index-v${VERSION}.html"; exit "$rc"; }
trap on_exit EXIT
CHANGED=1
pct push "$VMID" "/tmp/jns-netmon-app-v${VERSION}.py" "$APP_DIR/app.py" -perms 644
pct push "$VMID" "/tmp/jns-netmon-index-v${VERSION}.html" "$APP_DIR/index.html" -perms 644
pct exec "$VMID" -- python3 -m py_compile "$APP_DIR/app.py"
pct exec "$VMID" -- systemctl restart "$SERVICE"
HEALTH=""
for _ in $(seq 1 60); do
  HEALTH="$(pct exec "$VMID" -- curl -fsS --max-time 4 http://127.0.0.1:8081/health 2>/dev/null || true)"
  if grep -q '"version":"'"$VERSION"'"' <<<"$HEALTH"; then break; fi
  sleep 1
done
grep -q '"version":"'"$VERSION"'"' <<<"$HEALTH" || fail "Health/version check failed: $HEALTH"
READY=0
VALIDATION=""
for _ in $(seq 1 18); do
  STATE="$(pct exec "$VMID" -- curl -fsS --max-time 35 http://127.0.0.1:8081/api/state 2>/dev/null || true)"
  if VALIDATION="$(python3 - "$STATE" <<'PYVERIFY'
import json,sys
try:
    s=json.loads(sys.argv[1])
except Exception as exc:
    raise SystemExit(f"State API did not return JSON: {exc}")
if not isinstance(s.get("devices"),list) or not isinstance(s.get("links"),list):
    raise SystemExit("State API is missing devices/links arrays")
if not s.get("updated"):
    raise SystemExit("Collector has not completed an initial state update")
print("API state is valid:",len(s["devices"]),"devices;",len(s["links"]),"links")
PYVERIFY
)"; then READY=1; break; fi
  sleep 5
done
[[ $READY -eq 1 ]] || fail "Live API verification did not stabilize within the retry window."
python3 - "$HTML_B64" "$APP_B64" <<'PYVERIFY_PAYLOAD'
import base64,sys
h=base64.b64decode(sys.argv[1]).decode(); a=base64.b64decode(sys.argv[2]).decode()
assert "VLAN overlay" in h and "Q-BRIDGE-MIB" in h and "parse_vlans" in a
print("VLAN UI and collector payload checks passed")
PYVERIFY_PAYLOAD
echo "$VALIDATION"
UI="$(pct exec "$VMID" -- curl -fsS --max-time 5 http://127.0.0.1:8081/)"
grep -q 'id="device-dialog"' <<<"$UI" || fail "Device detail dialog missing from served UI."
grep -q 'function drawLinks' <<<"$UI" || fail "Topology link renderer missing from served UI."
grep -q 'quick-panel' <<<"$UI" || fail "Hover/touch quick detail panel missing from served UI."
grep -q 'function clusterFor(d)' <<<"$UI" || fail "Role and host clustering missing from served UI."
grep -q 'Proxmox · ' <<<"$UI" || fail "Proxmox host group labels missing from served UI."
grep -q 'hostBindings' <<<"$UI" || fail "Verified Proxmox host associations missing from served UI."
grep -q 'guestHost' <<<"$UI" || fail "Switch-port guest/host correlation missing from served UI."
grep -q 'function renderGroupDialog' <<<"$UI" || fail "Zoomable group view missing from served UI."
grep -q 'Core network · measured live links' <<<"$UI" || fail "Centered core map missing from served UI."
grep -q 'Focus a group or core device for port-level detail' <<<"$UI" || fail "Focus instructions missing from served UI."
grep -q 'healthColour' <<<"$UI" || fail "Health halo mapping missing from served UI."
grep -q 'VLAN configuration' <<<"$UI" || fail "VLAN detail panel missing from served UI."
grep -q 'VLAN overlay' <<<"$UI" || fail "Optional VLAN topology overlay missing from served UI."
grep -q 'function renderLinkDetails' <<<"$UI" || fail "Link detail window missing from served UI."
grep -q 'Active WANs' <<<"$UI" || fail "WAN detail missing from served UI."
grep -q 'function linkLoad' <<<"$UI" || fail "Load-weighted link rendering missing from served UI."
grep -q 'Topology connections' <<<"$UI" || fail "Device topology detail missing from served UI."
grep -q 'Peer port / ID' <<<"$UI" || fail "Peer port identifier label missing from served UI."
grep -q 'wifi_client' <<<"$UI" || fail "Wi-Fi client node rendering missing from served UI."
grep -q 'nas:' <<<"$UI" || fail "NAS node rendering missing from served UI."
grep -q 'id="focus-toggle"' <<<"$UI" || fail "Focus links control missing from served UI."
grep -q 'link-flow' <<<"$UI" || fail "Live traffic activity styling missing from served UI."
grep -q 'link-rate-label' <<<"$UI" || fail "Inline measured RX/TX labels missing from served UI."
grep -q 'REFRESH ERROR' <<<"$UI" || fail "Refresh failure state missing from served UI."
grep -q 'group-traffic' <<<"$UI" || fail "Group traffic summary missing from served UI."
grep -q 'Measured links' <<<"$UI" || fail "Measured-link summary missing from served UI."
grep -q '<th>In errors</th>' <<<"$UI" || fail "Interface error counters missing from served UI."
grep -q '<th>Out discards</th>' <<<"$UI" || fail "Interface discard counters missing from served UI."
pct exec "$VMID" -- rm -f "/tmp/jns-netmon-app-v${VERSION}.py" "/tmp/jns-netmon-index-v${VERSION}.html"
rm -f "/tmp/jns-netmon-app-v${VERSION}.py" "/tmp/jns-netmon-index-v${VERSION}.html"
CHANGED=0
trap - EXIT
echo "SUCCESS: JNS Network Monitor v${VERSION} is active."
echo "Backup: CT130:${BACKUP}"
echo "Centered core map with switch-port VLAN detail, optional VLAN topology labels, all-device distant view, live syslog overlay, and link health colours."
echo "No CT130 reinstall, network, LibreNMS, Grafana, or syslog service/config changes."
